func (this *Test_org_eclipse_swt_widgets_Display) Test_postLorg_eclipse_swt_widgets_Event() {
	var KEYCODE int32 = swt.SHIFT
	var display *swt.Display = swt.NewDisplay()
	{
		defer func() {
			display.Dispose()
		}()
		var ex *jrt.IllegalArgumentException = junit.AssertThrows[*jrt.IllegalArgumentException](func() {
			display.Post(nil)
		}, "No exception thrown for post with null argument")
		SwtTestUtilAssertSWTProblem("Incorrect exception thrown for post with null argument", swt.ERROR_NULL_ARGUMENT, ex)
		var shell *swt.Shell = swt.NewShellDisplayStyle(display, swt.NO_TRIM)
		shell.SetBoundsRect(display.GetBounds())
		SwtTestUtilOpenShell(shell)
		var event *swt.Event
		event = swt.NewEvent()
		event.Type = swt.KeyDown
		event.KeyCode = -1
		junit.AssertTrue(display.Post(event), "Display#post failed, probably because screen is not rendered (bug 407862) or because Shell is not focussed")
		event = swt.NewEvent()
		event.Type = swt.KeyUp
		junit.AssertTrue(display.Post(event))
		event.Type = swt.KeyDown
		event.KeyCode = KEYCODE
		shell.SetFocus()
		junit.AssertTrue(display.Post(event))
		event.Type = swt.KeyUp
		shell.SetFocus()
		junit.AssertTrue(display.Post(event))
		event = swt.NewEvent()
		event.Type = swt.MouseMove
		var bounds *swt.Rectangle = shell.GetBounds()
		event.X = bounds.X + bounds.Width/2
		event.Y = bounds.Y + bounds.Height/2
		shell.SetFocus()
		junit.AssertTrue(display.Post(event))
		event = swt.NewEvent()
		event.Type = swt.MouseDown
		if !SwtTestUtilIsGTK {
			junit.AssertFalse(display.Post(event))
		}
		event.Button = 1
		shell.SetFocus()
		junit.AssertTrue(display.Post(event))
		event = swt.NewEvent()
		event.Type = swt.MouseUp
		if !SwtTestUtilIsGTK {
			junit.AssertFalse(display.Post(event))
		}
		event.Button = 1
		shell.SetFocus()
		junit.AssertTrue(display.Post(event))
		event = swt.NewEvent()
		event.Type = swt.MouseDoubleClick
		junit.AssertFalse(display.Post(event))
		Test_org_eclipse_swt_widgets_DisplayDrainEventQueue(display, 500)
		shell.Dispose()
	}
}

