func (this *Test_org_eclipse_swt_widgets_Display) Test_timerExecILjava_lang_Runnable() {
	var display *swt.Display = swt.NewDisplay()
	{
		defer func() {
			display.Dispose()
		}()
		var timerExecRan []bool = []bool{false}
		var threadRan []bool = []bool{false}
		var e *jrt.IllegalArgumentException = junit.AssertThrows[*jrt.IllegalArgumentException](func() {
			display.TimerExec(0, nil)
		}, "No exception thrown for timerExec with null runnable")
		SwtTestUtilAssertSWTProblem("Incorrect exception thrown for timerExec with null runnable", swt.ERROR_NULL_ARGUMENT, e)
		display.TimerExec(-100, jrt.NewRunnable(func() {
			timerExecRan[0] = true
		}))
		var delay int32 = 3000
		var startTime int64 = jrt.CurrentTimeMillis()
		display.TimerExec(delay, jrt.NewRunnable(func() {
			var endTime int64 = jrt.CurrentTimeMillis()
			if endTime < (startTime + int64(delay)) {
				fmt.Fprintln(os.Stdout, fmt.Sprintf("Display.timerExec ran early %d", ((startTime+int64(delay))-endTime)))
			}
			threadRan[0] = true
		}))
		for !threadRan[0] {
			if !display.ReadAndDispatch() {
				display.Sleep()
			}
		}
		junit.AssertFalse(timerExecRan[0], "< 0 ms timer did execute")
	}
}

