func Test_org_eclipse_swt_widgets_DisplayDrainEventQueue(displayLike swt.DisplayLike, millis int32) {
	var display *swt.Display
	if displayLike != nil {
		display = displayLike.AsDisplay()
	}
	_ = display
	if millis == 0 {
		for !display.IsDisposed() && display.ReadAndDispatch() {
		}
		return
	}
	var end int64 = jrt.CurrentTimeMillis() + int64(millis)
	for !display.IsDisposed() && jrt.CurrentTimeMillis() < end {
		if !display.ReadAndDispatch() {
			func() {
				defer func() {
					r := recover()
					if r == nil {
						return
					}
					if false {
						var e error
						_ = e
						fmt.Fprintln(os.Stderr, e)
					} else {
						panic(r)
					}
				}()
				jrt.Sleep(int64(10))
			}()
		}
	}
}

